    for s in range(n):
        for i in range(n):
            if a[i] < a[s]:
                d[s][i] = -INF
            else:
                d[s][i] = 1
                for j in range(i):
                    if a[j] <= a[i]:
                        if d[s][j] + 1 > d[s][i]:
                            d[s][i] = d[s][j] + 1

    def one(mat):
        for i in range(n):
            for j in range(n):
                mat[i][j] = 0

    def copy_mat(src, dest):
        for i in range(n):
            for j in range(n):
                dest[i][j] = src[i][j]

    def mul(a_mat, b_mat, c_mat):
        for i in range(n):
            for j in range(n):
                max_val = -INF
                for k in range(n):
                    val = a_mat[i][k] + b_mat[k][j]
                    if val > max_val:
                        max_val = val
                c_mat[i][j] = max_val

    def binpow(a_mat, power, res_mat):
        copy_mat(a_mat, t)
        one(res_mat)
