import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    T = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    INF = 10**15

    # Initialize base matrix d
    d = [[-INF] * n for _ in range(n)]
    for s in range(n):
        for i in range(n):
            if a[i] < a[s]:
                d[s][i] = -INF
            else:
                d[s][i] = 1
                for j in range(i):
                    if a[j] <= a[i]:
                        if d[s][j] + 1 > d[s][i]:
                            d[s][i] = d[s][j] + 1

    def mat_mul(A, B):
        # Max-plus multiplication
        C = [[-INF] * n for _ in range(n)]
        for i in range(n):
            Ai = A[i]
            Ci = C[i]
            for k in range(n):
                aik = Ai[k]
                if aik == -INF:
                    continue
                Bk = B[k]
                # Unroll inner loop slightly or keep standard
                for j in range(n):
                    val = aik + Bk[j]
                    if val > Ci[j]:
                        Ci[j] = val
        return C

    def mat_pow(base, exp):
        # Identity matrix for max-plus: 0 on diag, -INF elsewhere
        res = [[-INF] * n for _ in range(n)]
        for i in range(n):
            res[i][i] = 0

        while exp > 0:
            if exp & 1:
                res = mat_mul(res, base)
            base = mat_mul(base, base)
            exp >>= 1
        return res

    dt = mat_pow(d, T)

    ans = 0
    for i in range(n):
        for j in range(n):
            if dt[i][j] > ans:
                ans = dt[i][j]

    print(ans)

if __name__ == "__main__":
    solve()

